input.command:
S=/private/tmp/claude-501/-Users-kentgang-git3-katalyst/3bcc9024-06ad-4692-9a6a-e303e34756e0/scratchpad; W=/Users/kentgang/git3/katalyst-wt/feat-03b-canvas
cd $W/backend && (env -u ANTHROPIC_API_KEY -u FRED_API_KEY nohup uv run uvicorn katalyst.api.main:app --port 8011 > $S/coord-backend.log 2>&1 &) 
cd $W/frontend && (KATALYST_API_URL=http://localhost:8011 nohup npm run dev -- --port 5184 --strictPort > $S/coord-vite.log 2>&1 &)
for i in $(seq 1 30); do curl -sf http://localhost:5184/api/healthz >/dev/null 2>&1 && break; sleep 1; done; curl -s http://localhost:5184/api/healthz; echo
cat > $S/coord-shoot.mjs <<'EOF'
import { chromium } from "playwright";
const out = process.argv[2];
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1600, height: 1000 }, deviceScaleFactor: 1 });
await p.goto("http://localhost:5184/");
await p.waitForTimeout(800);
await p.screenshot({ path: `${out}/coord-01-launchpad.png` });
await p.getByText("Open the map").click();
await p.waitForTimeout(2500);
await p.screenshot({ path: `${out}/coord-02-map.png` });
// keyboard only: tab to a chip and see the shelf
for (let i = 0; i < 8; i++) await p.keyboard.press("Tab");
await p.waitForTimeout(400);
await p.screenshot({ path: `${out}/coord-03-tabbed.png` });
const w = await p.evaluate(() => { const t = document.querySelector(".react-flow__node"); const r = t.getBoundingClientRect(); const z = new DOMMatrix(getComputedStyle(document.querySelector(".react-flow__viewport")).transform).a; return { w: r.width / z, h: r.height / z, z, dialogs: document.querySelectorAll("[role=dialog],dialog").length, fonts: getComputedStyle(t).fontFamily.slice(0, 40) }; });
console.log(JSON.stringify(w));
await b.close();
EOF
cd $S && node coord-shoot.mjs $S/c-shots 2>&1 | tail -3

